#include <vector>
#include <string>
#include <zlib.h>

// Função para ler o conteúdo de um arquivo em memória
std::vector<uint8_t> lerArquivo(const std::string& caminho) {
 std::ifstream arquivo(caminho, std::ios::binary);
 if (!arquivo) {
 std::cerr << "Erro ao abrir o arquivo: " << caminho << std::endl;
 return {};
 }
 arquivo.seekg(0, std::ios::end);
 size_t tamanho = arquivo.tellg();
 arquivo.seekg(0, std::ios::beg);
 std::vector<uint8_t> dados(tamanho);
 arquivo.read(reinterpret_cast<char*>(dados.data()), tamanho);
 return dados;
}

// Função para comprimir os bytes (retorna um vetor com os bytes comprimidos)
std::vector<uint8_t> comprimir(const std::vector<uint8_t>& dadosOriginais) {
 std::vector<uint8_t> buffer;
 uLongf comprimentoSaida = compressBound(dadosOriginais.size());
 buffer.resize(comprimentoSaida);

 int status = compress(buffer.data(), &comprimentoSaida,
 const_cast<uint8_t*>(dadosOriginais.data()),
 dadosOriginais.size());

 if (status != Z_OK) {
 std::cerr << "Falha na compressão: " << status << std::endl;
 return {};
 }

 // Reduz o tamanho do buffer para o valor real
 buffer.resize(comprimentoSaida);
 return buffer;
}

// Função de leitura/descompressão dos bytes comprimidos
std::vector<uint8_t> descomprimir(const std::vector<uint8_t>& dadosComprimidos) {
 std::vector<uint8_t> resultado;
 int status = uncompress(resultado.data(), &resultado.size(),
 dadosComprimidos.data(),
 dadosComprimidos.size());
 if (status != Z_OK) {
