 if (dadosOriginais.empty()) {
 std::cout << "Nenhum dado lido. Encerrando." << std::endl;
 return 1;
 }

 std::cout << "Tamanho original: " << dadosOriginais.size() << " bytes" << std::endl;

 // 2. Comprimir os bytes
